  s = dst_ctx->flush();
  if (!s.ok()) {
    LOG_ERROR("ReduceFts: flush destination FTS RocksDB failed: %s",
              s.message().c_str());
    (void)dst_ctx->close();
    return s;
  }
  s = dst_ctx->close();
  if (!s.ok()) {
    LOG_ERROR("ReduceFts: close destination FTS RocksDB failed: %s",
              s.message().c_str());
    return s;
  }

